const nodemailer = require('nodemailer');

const smtpHost = $input.first().json.smtp_host;
const smtpPort = $input.first().json.smtp_port;
const smtpUser = $input.first().json.smtp_user;
const smtpPass = $input.first().json.smtp_pass;

const to = $input.first().json.recipient;
const subject = $input.first().json.subject;
const body = $input.first().json.body;

const html = `<div>${body}</div>`;

// массив логов
let logs = [];

// утилита для задержки
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function sendEmailOnce(attempt) {
  const transporter = nodemailer.createTransport({
    host: smtpHost,
    port: smtpPort,
    secure: true,
    auth: {
      user: smtpUser,
      pass: smtpPass,
    },
  });

  const message = {
    from: smtpUser,
    to,
    subject: subject,
    html,
    headers: {
      'Disposition-Notification-To': smtpUser,
      'Return-Receipt-To': smtpUser,
      'X-Confirm-Reading-To': smtpUser,
      'Errors-To': smtpUser,
    }
  };

  try {
    const info = await transporter.sendMail(message);
    logs.push({ attempt, status: "success", messageId: info.messageId });
    return String(info.messageId); // без лишней проверки accepted[]
  } catch (err) {
    logs.push({ attempt, status: "error", error: err.message });
    return -1;
  }
}

async function sendEmailWithRetry(maxAttempts = 5, delayMs = 5000) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    logs.push({ attempt, info: `Попытка ${attempt} из ${maxAttempts}` });
    const messageId = await sendEmailOnce(attempt);

    if (messageId !== -1) {
      return messageId;
    }

    if (attempt < maxAttempts) {
      logs.push({ attempt, info: `Ожидание ${delayMs / 1000} секунд перед следующей попыткой` });
      await sleep(delayMs);
    }
  }
  return -1;
}

const message_id = await sendEmailWithRetry(1, 5000);

if (message_id == -1) {
  $input.first().json.smtp = false;
} else {
  $input.first().json.message_id = message_id;
  $input.first().json.smtp = true;
}

// прикрепляем логи
$input.first().json.log = logs;

return $input.first().json;

const Imap = require('imap');

const originalMessageId = $input.first().json.message_id;

const imapHost = $input.first().json.imap_host;
const imapPort = $input.first().json.imap_port;
const imapUser = $input.first().json.imap_user;
const imapPass = $input.first().json.imap_pass;

const to = $input.first().json.recipient;
const subject = $input.first().json.subject;
const body = $input.first().json.body;

const html = `<div>${body}</div>`;

function normalizeMessageId(id) {
  return id.startsWith('<') ? id : `<${id}>`;
}

function saveEmail() {
  return new Promise((resolve, reject) => {
    try {
      const imap = new Imap({
        user: imapUser,
        password: imapPass,
        host: imapHost,
        port: imapPort,
        tls: true,
      });

      const encodedSubject = `=?UTF-8?B?${Buffer.from(subject, 'utf-8').toString('base64')}?=`;

      imap.once('ready', function () {
        const rawMessage = [
          `From: ${imapUser}`,
          `To: ${to}`,
          `Subject: ${encodedSubject}`,
          `Date: ${new Date().toUTCString()}`,
          `Message-ID: ${normalizeMessageId(originalMessageId)}`,
          `MIME-Version: 1.0`,
          `Content-Type: text/html; charset=UTF-8`,
          `Content-Transfer-Encoding: 7bit`,
          '',
          html,
        ].join('\r\n');

        const sentFolder = 'Рассылки|Отправленные';
        let res;
        imap.append(rawMessage, { mailbox: sentFolder, flags: ['\\Seen'] }, function (err) {
          if (err) {
            console.log('❌ Ошибка при сохранении в "Отправленные":', err);
            res = false;
          } else {
            console.log('📩 Скопировано в "Отправленные"');
            res = true;
          }
          imap.end();
          resolve(res);
        });
      });

      imap.once('error', function (err) {
        console.log('IMAP ошибка:', err);
        resolve(false);
      });

      imap.connect();
    } catch (err) {
      console.log('🚨 Исключение при соединении с IMAP:', err);
      resolve(false);
    }
  });
}


const res = await saveEmail();
$input.first().json.imap = res;
return $input.first().json;

// Начальное и конечное значение
const min = 2;
const max = 3;

// Обрабатываем каждый элемент
for (const item of $input.all()) {
  // Генерируем случайное число от min до max
  const randomFloat = Math.random() * (max - min) + min;
  item.json.random_wait = randomFloat;
}

return $input.all();

